<script setup lang="ts">
import {ref} from 'vue';import {open,save as saveDialog} from '@tauri-apps/plugin-dialog';import {ElMessage,ElMessageBox} from 'element-plus';import {FolderOpen,Download,KeyRound} from 'lucide-vue-next';import {useAppStore,defaults,time} from '../store';
const app=useAppStore();const s=ref({...app.data?.settings??defaults});const saving=ref(false),apiKey=ref(''),json=ref(app.data?.benchmark?JSON.stringify(app.data.benchmark.config,null,2):''),bmBusy=ref(false);
const template={name:'Viscose Benchmarks S2',version:'S2',difficulty:'Easier',source:'填写已核对的公开来源 URL',ranks:[],scenarios:[]};
async function pick(){try{const p=await open({directory:true,multiple:false,title:'选择 KovaaK Stats 文件夹'});if(typeof p==='string')s.value.stats_dir=p;}catch(e){ElMessage.error(String(e));}}
async function detect(){try{const found=await app.call<string[]>('detect_stats');if(found[0]){s.value.stats_dir=found[0];ElMessage.success(`找到 ${found.length} 个目录，已填入首个`);}else{ElMessage.info('未自动找到 Stats，请手动选择');}}catch(e){ElMessage.error(String(e));}}
async function save(){saving.value=true;try{await app.save(s.value);ElMessage.success('设置已保存');return true;}catch(e){ElMessage.error(String(e));return false;}finally{saving.value=false;}}
async function scan(force=false){if(await save())await app.scan(force);}
async function loadJson(){try{const p=await open({multiple:false,filters:[{name:'Benchmark JSON',extensions:['json']}]});if(typeof p==='string')json.value=await app.call<string>('read_benchmark_file',{path:p});}catch(e){ElMessage.error(String(e));}}
async function importJson(){bmBusy.value=true;try{await app.call('import_benchmark',{json:json.value});await app.refresh();ElMessage.success('Benchmark 已校验并导入');}catch(e){ElMessage.error(String(e));}finally{bmBusy.value=false;}}
async function saveKey(){try{await app.call('save_api_key',{key:apiKey.value});apiKey.value='';await app.refresh();ElMessage.success('API Key 已写入 Windows 凭据管理器');}catch(e){ElMessage.error(String(e));}}
async function deleteKey(){try{await app.call('delete_api_key');await app.refresh();ElMessage.success('已删除 API 凭据');}catch(e){ElMessage.error(String(e));}}
async function consent(v:string|number|boolean){if(!v){s.value.ai_consent=false;return;}s.value.ai_consent=false;try{await ElMessageBox.confirm('开启后，每次点击“请求 AI 补充解释”都会将场景名称、样本数量、聚合统计、训练目标与建议发送到你配置的外部 API。源文件路径、原始 CSV 和 API Key 不作为分析数据发送。服务提供方可能保存请求内容。是否授权？','授权聚合训练数据离开本机',{confirmButtonText:'授权发送聚合数据',cancelButtonText:'保持本地分析',type:'warning'});s.value.ai_consent=true;}catch{/* cancelled */}}
async function backup(){try{const p=await saveDialog({defaultPath:`aimcoach-backup-${Date.now()}.sqlite`,filters:[{name:'SQLite 备份',extensions:['sqlite']}]});if(p){await app.call('backup_database',{target:p});ElMessage.success(`备份已保存：${p}`);}}catch(e){ElMessage.error(String(e));}}
</script>
<template><section class="panel"><div class="panel-heading"><div><span class="eyebrow">DATA CONNECTION</span><h3>KovaaK 训练数据</h3></div><span class="status improved">只读访问原始 CSV</span></div><el-form label-position="top"><el-form-item label="Stats 文件夹"><div class="path-input"><el-input v-model="s.stats_dir" placeholder="例如 E:\SteamLibrary\steamapps\common\FPSAimTrainer\FPSAimTrainer\stats"/><el-button :disabled="app.preview" @click="pick"><FolderOpen :size="16"/> 选择目录</el-button><el-button :disabled="app.preview" @click="detect">自动查找</el-button></div></el-form-item><div class="preferences"><label>自动监听<el-switch v-model="s.auto_watch" active-text="写入稳定后导入"/></label><label>会话间隔（产品规则）<el-input-number v-model="s.session_gap_minutes" :min="1" :max="180"/><small class="muted">默认20分钟，不是 KovaaK 官方定义</small></label></div><div class="toolbar"><el-button type="primary" :loading="saving" :disabled="app.preview" @click="save">保存设置</el-button><el-button :loading="app.syncing" :disabled="app.preview||!s.stats_dir" @click="scan(false)">扫描历史记录</el-button><el-button :loading="app.syncing" :disabled="app.preview||!s.stats_dir" @click="scan(true)">重新解析全部历史</el-button></div></el-form><div class="sync-summary"><span>最近同步 {{time(app.data?.sync.finished_at)}}</span><span>新增 {{app.data?.sync.imported??'—'}} · 更新 {{app.data?.sync.updated??'—'}} · 跳过 {{app.data?.sync.skipped??'—'}} · 失败 {{app.data?.sync.failed??'—'}} · 待文件写完 {{app.data?.sync.deferred??'—'}}</span></div><p class="muted small">文件修改不到2秒或读取期间发生变化会暂缓；自动监听开启时会继续检查。手动扫描遇到暂缓文件可稍后再次扫描。重新解析会更新同一次训练，不清空历史。</p><el-collapse v-if="app.data?.sync.errors.length"><el-collapse-item title="查看导入失败原因" name="errors"><p v-for="e in app.data.sync.errors" :key="e" class="error-text">{{e}}</p></el-collapse-item></el-collapse></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">BENCHMARK CONFIGURATION</span><h3>Benchmark JSON 与场景别名</h3></div><el-button :disabled="app.preview" @click="loadJson">从文件载入</el-button></div><p class="muted">完整配置通过校验后才会生效。等级顺序由 ranks 定义；每场景必须包含全部等级且分数严格递增。aliases 可关联导入场景名称。任意大类和子类均来自配置。</p><el-input v-model="json" type="textarea" :rows="12" placeholder="粘贴 Benchmark JSON；README 提供结构和合成示例（不作为正式门槛）" class="json-editor"/><div class="toolbar"><el-button type="primary" :loading="bmBusy" :disabled="app.preview||!json.trim()" @click="importJson">校验并导入配置</el-button><el-button @click="json=JSON.stringify(template,null,2)">填入 Viscose 空模板</el-button><el-button v-if="app.data?.benchmark" @click="json=JSON.stringify(app.data.benchmark.config,null,2)">载入当前配置</el-button></div><p class="muted small">空模板没有门槛，必须填入核实过的真实场景和分数。系统不会自动补齐或猜测。</p></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">OPTIONAL AI</span><h3>OpenAI-compatible 智能解释</h3></div><span class="status">{{app.data?.key_configured?'系统凭据已配置':'未配置凭据'}}</span></div><el-form label-position="top"><div class="two-col"><el-form-item label="API Base URL（包含 /v1，按提供方文档）"><el-input v-model="s.ai_base_url" placeholder="https://api.example.com/v1"/></el-form-item><el-form-item label="Model"><el-input v-model="s.ai_model" placeholder="填写提供方的模型标识"/></el-form-item></div><el-form-item label="API Key（仅保存到 Windows 凭据管理器）"><div class="path-input"><el-input v-model="apiKey" type="password" show-password autocomplete="off" placeholder="输入后点击保存凭据；不会回填已有 Key"/><el-button :disabled="app.preview||!apiKey" @click="saveKey"><KeyRound :size="15"/> 保存凭据</el-button><el-button :disabled="app.preview||!app.data?.key_configured" @click="deleteKey">删除凭据</el-button></div></el-form-item><el-form-item label="外部数据授权"><el-switch :model-value="s.ai_consent" @change="consent" active-text="允许显式请求 AI 时发送聚合统计"/></el-form-item><p class="muted small">默认关闭。保存授权后，仍需要在教练页面主动点击请求；自动同步只生成本地报告。AI 失败会回退本地规则。未对 LLM 输出的每一句进行自动事实认证，请以确定性证据为准。</p><el-button type="primary" :loading="saving" :disabled="app.preview" @click="save">保存模型配置与授权</el-button></el-form></section><section class="panel"><h3>本地数据管理</h3><p class="muted">数据库：{{app.data?.db_path??'浏览器预览未打开数据库'}}</p><el-button :disabled="app.preview" @click="backup"><Download :size="15"/> 导出 SQLite 备份</el-button><p class="muted small">包含训练记录、原始字段映射、配置与报告；API Key 保存在系统凭据中，不在备份内。备份文件请保存在 Stats 目录之外。</p></section></template>
